// Build the INSERT statement for a failed sync run.
// Uses a dual-shape extraction: nested execution.error shape first,
// then the flat error payload shape as fallback.

const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const trigger = $input.all()[i].json;

  // Try the nested shape first (full execution payload)
  let executionId = null;
  let errorNode = null;
  let errorMessage = null;
  let errorClass = null;
  let executionUrl = null;

  if (trigger.execution) {
    executionId = trigger.execution.id ? String(trigger.execution.id) : null;
    executionUrl = trigger.execution.url || null;
    if (trigger.execution.error) {
      errorClass = trigger.execution.error.name || null;
      errorMessage = trigger.execution.error.description || trigger.execution.error.message || null;
      if (trigger.execution.error.node) {
        errorNode = trigger.execution.error.node.name || null;
      }
    }
    if (!errorNode && trigger.execution.lastNodeExecuted) {
      errorNode = trigger.execution.lastNodeExecuted;
    }
  }

  // Fall back to the flat shape
  if (!errorNode && trigger.lastNodeExecuted) {
    errorNode = trigger.lastNodeExecuted;
  }
  if (!errorMessage && trigger.message) {
    errorMessage = trigger.message;
  }
  if (!errorClass && trigger.name) {
    errorClass = trigger.name;
  }

  const workflowName = (trigger.workflow && trigger.workflow.name) || 'Shopify to HubSpot Customer Sync';
  const errorTimestamp = (trigger.executionContext && trigger.executionContext.establishedAt)
    ? trigger.executionContext.establishedAt
    : Date.now();

  // Build a unique run_id for the failure row
  const runId = executionId
    ? 'error-exec-' + executionId
    : 'error-' + errorTimestamp;

  // Compose the full error message
  const parts = [];
  if (errorClass) parts.push(errorClass);
  if (errorNode) parts.push(errorNode);
  if (errorMessage) parts.push(errorMessage);
  if (executionUrl) parts.push(executionUrl);
  const fullMessage = parts.join(': ').slice(0, 1000);

  const esc = (v) => {
    if (v === null || v === undefined) return 'NULL';
    return "'" + String(v).replace(/'/g, "''") + "'";
  };

  const sql = `INSERT INTO customer_sync_runs (
    run_id,
    started_at,
    finished_at,
    customers_fetched,
    contacts_upserted,
    skipped_no_email,
    status,
    error_message
  ) VALUES (
    ${esc(runId)},
    NOW(),
    NOW(),
    0,
    0,
    0,
    'failed',
    ${esc(fullMessage)}
  )
  ON CONFLICT (run_id) DO UPDATE SET
    status = 'failed',
    error_message = EXCLUDED.error_message,
    finished_at = NOW();`;

  results.push({
    json: {
      run_id: runId,
      workflow_name: workflowName,
      error_node: errorNode,
      error_class: errorClass,
      error_message: fullMessage,
      sql_query: sql
    }
  });
}

return results;
